"use client";

import { useRef, useState, useEffect } from "react";
import Link from "next/link";
import Matter from "matter-js";
import { useGSAP } from "@gsap/react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { useLenis } from "lenis/react";
import styles from "./Footer.module.css";

gsap.registerPlugin(ScrollTrigger, useGSAP);

const OBJECTS = [
	"Illustration",
	"Characters",
	"Motion",
	"Murals",
	"Comics",
	"Mascots",
	"Covers",
	"Posters",
	"Branding",
	"Type",
	"Zines",
	"Sketchbook",
	"Ink",
	"Storyboards",
	"Loops",
	"Key Art",
	"Doodles",
	"Packaging",
	"Editorial",
	"Stickers",
	"Worldbuilding",
	"Concepts",
	"Animation",
	"Chaos",
];

const NAV = [
	{
		title: "Studio",
		links: [
			{ label: "About", href: "/about" },
			{ label: "Work", href: "/work" },
			{ label: "Expertise", href: "/expertise" },
		],
	},
	{
		title: "Company",
		links: [
			{ label: "Careers", href: "/careers" },
			{ label: "Contact", href: "/contact" },
		],
	},
];

const SOCIAL = [
	{ label: "Instagram", href: "/" },
	{ label: "LinkedIn", href: "/" },
	{ label: "X", href: "/" },
];

const PILL_VARIANTS = [styles.v1, styles.v2, styles.v3, styles.v4];

function shuffle(items) {
	const next = [...items];
	for (let i = next.length - 1; i > 0; i--) {
		const j = Math.floor(Math.random() * (i + 1));
		[next[i], next[j]] = [next[j], next[i]];
	}
	return next;
}

function evenlyDistributedVariants(count) {
	return Array.from(
		{ length: count },
		(_, i) => PILL_VARIANTS[i % PILL_VARIANTS.length],
	);
}

function distributeVariants(count) {
	return shuffle(evenlyDistributedVariants(count));
}

const CONFIG = {
	gravity: { x: 0, y: 1 },
	restitution: 0.5,
	friction: 0.15,
	frictionAir: 0.02,
	density: 0.002,
	wallThickness: 200,
	mouseStiffness: 0.6,
};

function clamp(val, min, max) {
	return Math.max(min, Math.min(max, val));
}

export default function Footer() {
	const sectionRef = useRef(null);
	const containerRef = useRef(null);
	const [pillVariants, setPillVariants] = useState(() =>
		evenlyDistributedVariants(OBJECTS.length),
	);

	useEffect(() => {
		setPillVariants(distributeVariants(OBJECTS.length));
	}, []);

	useLenis(() => {
		ScrollTrigger.update();
	});

	useGSAP(
		() => {
			const section = sectionRef.current;
			const container = containerRef.current;
			if (!section || !container) return;

			let engine = null;
			let runner = null;
			let topWall = null;
			let topWallTimeout = null;
			let rafId = 0;
			const bodies = [];
			const cleanupFns = [];

			const initPhysics = () => {
				if (engine) return;

				engine = Matter.Engine.create();
				engine.gravity.x = CONFIG.gravity.x;
				engine.gravity.y = CONFIG.gravity.y;
				engine.constraintIterations = 10;
				engine.positionIterations = 20;
				engine.velocityIterations = 16;
				engine.timing.timeScale = 1;

				const containerRect = container.getBoundingClientRect();
				const wallThickness = CONFIG.wallThickness;

				const walls = [
					Matter.Bodies.rectangle(
						containerRect.width / 2,
						containerRect.height + wallThickness / 2,
						containerRect.width + wallThickness * 2,
						wallThickness,
						{ isStatic: true },
					),
					Matter.Bodies.rectangle(
						-wallThickness / 2,
						containerRect.height / 2,
						wallThickness,
						containerRect.height + wallThickness * 2,
						{ isStatic: true },
					),
					Matter.Bodies.rectangle(
						containerRect.width + wallThickness / 2,
						containerRect.height / 2,
						wallThickness,
						containerRect.height + wallThickness * 2,
						{ isStatic: true },
					),
				];
				Matter.World.add(engine.world, walls);

				const objects = container.querySelectorAll(`.${styles.object}`);
				objects.forEach((obj, index) => {
					const objRect = obj.getBoundingClientRect();
					const startX =
						Math.random() * (containerRect.width - objRect.width) +
						objRect.width / 2;
					const startY = -500 - index * 100;
					const startRotation = (Math.random() - 0.5) * Math.PI;

					const body = Matter.Bodies.rectangle(
						startX,
						startY,
						objRect.width,
						objRect.height,
						{
							restitution: CONFIG.restitution,
							friction: CONFIG.friction,
							frictionAir: CONFIG.frictionAir,
							density: CONFIG.density,
						},
					);

					Matter.Body.setAngle(body, startRotation);

					bodies.push({
						body,
						element: obj,
						width: objRect.width,
						height: objRect.height,
					});

					Matter.World.add(engine.world, body);
				});

				topWallTimeout = setTimeout(() => {
					if (!engine) return;
					topWall = Matter.Bodies.rectangle(
						containerRect.width / 2,
						-wallThickness / 2,
						containerRect.width + wallThickness * 2,
						wallThickness,
						{ isStatic: true },
					);
					Matter.World.add(engine.world, topWall);
				}, 3000);

				const getBounds = (width, height) => ({
					minX: width / 2,
					maxX: containerRect.width - width / 2,
					maxY: containerRect.height - height / 2,
				});

				const pointer = { x: 0, y: 0, lastX: 0, lastY: 0 };
				const INTERACT_RADIUS = 140;

				const scatterFromPointer = (clientX, clientY) => {
					const rect = container.getBoundingClientRect();
					const x = clientX - rect.left;
					const y = clientY - rect.top;
					const moveX = x - pointer.lastX;
					const moveY = y - pointer.lastY;

					pointer.x = x;
					pointer.y = y;
					pointer.lastX = x;
					pointer.lastY = y;

					if (Math.hypot(moveX, moveY) < 0.5) return;

					bodies.forEach(({ body }) => {
						const dx = body.position.x - x;
						const dy = body.position.y - y;
						const dist = Math.hypot(dx, dy) || 1;

						if (dist > INTERACT_RADIUS) return;

						const falloff = 1 - dist / INTERACT_RADIUS;
						const push = falloff * 0.9;

						Matter.Body.setVelocity(body, {
							x: clamp(
								body.velocity.x + (dx / dist) * push * 18 + moveX * 0.45,
								-20,
								20,
							),
							y: clamp(
								body.velocity.y + (dy / dist) * push * 18 + moveY * 0.45,
								-20,
								20,
							),
						});

						Matter.Body.setAngularVelocity(
							body,
							clamp(
								body.angularVelocity + moveX * 0.008 * falloff,
								-0.35,
								0.35,
							),
						);
					});
				};

				const onMouseMove = (e) => {
					scatterFromPointer(e.clientX, e.clientY);
				};

				const onTouchMove = (e) => {
					const touch = e.touches[0];
					if (!touch) return;
					scatterFromPointer(touch.clientX, touch.clientY);
				};

				const onPointerEnter = (e) => {
					const rect = container.getBoundingClientRect();
					const x = e.clientX - rect.left;
					const y = e.clientY - rect.top;
					pointer.x = pointer.lastX = x;
					pointer.y = pointer.lastY = y;
				};

				// Pills are not interactive on mobile.
				if (window.innerWidth >= 1000) {
					section.addEventListener("mousemove", onMouseMove);
					section.addEventListener("mouseenter", onPointerEnter);
					section.addEventListener("touchmove", onTouchMove, { passive: true });

					cleanupFns.push(() => {
						section.removeEventListener("mousemove", onMouseMove);
						section.removeEventListener("mouseenter", onPointerEnter);
						section.removeEventListener("touchmove", onTouchMove);
					});
				}

				Matter.Events.on(engine, "afterUpdate", () => {
					bodies.forEach(({ body, width, height }) => {
						const { minX, maxX, maxY } = getBounds(width, height);
						let { x, y } = body.position;
						let vx = body.velocity.x;
						let vy = body.velocity.y;
						let corrected = false;

						if (x < minX) {
							x = minX;
							vx = Math.abs(vx) * CONFIG.restitution;
							corrected = true;
						} else if (x > maxX) {
							x = maxX;
							vx = -Math.abs(vx) * CONFIG.restitution;
							corrected = true;
						}

						if (y > maxY) {
							y = maxY;
							vy = -Math.abs(vy) * CONFIG.restitution;
							corrected = true;
						}

						if (!corrected) return;

						Matter.Body.setPosition(body, { x, y });
						Matter.Body.setVelocity(body, { x: vx, y: vy });
					});
				});

				runner = Matter.Runner.create();
				Matter.Runner.run(runner, engine);

				const updatePositions = () => {
					bodies.forEach(({ body, element, width, height }) => {
						const x = clamp(
							body.position.x - width / 2,
							0,
							containerRect.width - width,
						);
						const y = clamp(
							body.position.y - height / 2,
							-height * 3,
							containerRect.height - height,
						);

						element.style.left = `${x}px`;
						element.style.top = `${y}px`;
						element.style.transform = `rotate(${body.angle}rad)`;
					});

					rafId = requestAnimationFrame(updatePositions);
				};

				updatePositions();
			};

			const trigger = ScrollTrigger.create({
				trigger: section,
				start: "top bottom",
				once: true,
				onEnter: () => {
					initPhysics();
				},
			});

			return () => {
				trigger.kill();
				clearTimeout(topWallTimeout);
				cancelAnimationFrame(rafId);
				cleanupFns.forEach((fn) => fn());

				if (runner) Matter.Runner.stop(runner);
				if (engine) {
					Matter.World.clear(engine.world, false);
					Matter.Engine.clear(engine);
				}

				engine = null;
				runner = null;
				topWall = null;
				bodies.length = 0;
			};
		},
		{ scope: sectionRef },
	);

	return (
		<footer
			className={styles.footer}
			ref={sectionRef}
		>
			<div
				className={styles.objectContainer}
				ref={containerRef}
			>
				{OBJECTS.map((label, i) => (
					<div
						key={label}
						className={`${styles.object} ${pillVariants[i]}`}
					>
						<p>{label}</p>
					</div>
				))}
			</div>

			<div className={styles.content}>
				<div className={`container pad ${styles.inner}`}>
					<div className={styles.top}>
						<div className={styles.brand}>
							<h2>A27 Web Lab</h2>
							<p>
								An illustration studio making brands, characters, and worlds.
							</p>
						</div>

						<div className={styles.columns}>
							{NAV.map((group) => (
								<div
									key={group.title}
									className={`${styles.column} ${styles.columnNav}`}
								>
									<p className="mono sm">{group.title}</p>
									<ul>
										{group.links.map((link) => (
											<li key={link.href}>
												<p>
													<Link href={link.href}>{link.label}</Link>
												</p>
											</li>
										))}
									</ul>
								</div>
							))}

							<div className={styles.column}>
								<p className="mono sm">Connect</p>
								<ul>
									{SOCIAL.map((link) => (
										<li key={link.label}>
											<p>
												<Link href={link.href}>{link.label}</Link>
											</p>
										</li>
									))}
								</ul>
							</div>
						</div>
					</div>

					<div className={styles.bottom}>
						<div className={styles.meta}>
							<p className="mono sm">California · Remote</p>
						</div>

						<div className={styles.legal}>
							<p className="mono sm">
								© {new Date().getFullYear()} A27 Web Lab
							</p>
							<p className="mono sm">Developed by A27 Web Lab</p>
							<p className="mono sm">All Rights Reserved</p>
						</div>
					</div>
				</div>
			</div>
		</footer>
	);
}
